  /\ sp mod 16 = 0 /\ hl_sptop L - 2 ^ 23 + 20480 <= sp /\ sp <= hl_sptop L /\ (0x7fff80000000 <= hl_sptop L <= 2 ^ 47)
  /\ sp <= fb /\ fb + 832 <= hl_sptop L /\ fb mod 16 = 0
