  getr Rq (PMK.reg 10) = Z_to_bv 64 (sp - 32) -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv -> L5.u64_at RSEGS Mq (sp - 32) (fb + 440) -> csl Rq ->
